namespace ScoreModern {public sealed partial class Editor {
 bool originalTextOtherFontPending;bool originalTextSetupActive;int originalTextSetupField;readonly float[] originalTextSetup={1,5,-3,1,1,0};InputFieldSpan[] originalTextSetupSpans;
 readonly SetupValueBox originalTextValueBox=new SetupValueBox();Font originalTextValueFont;
 void InitializeOriginalTextSetup(){command.TextChanged+=(sender,args)=>AutoCompleteOriginalText();contextLine.MouseClick+=(s,e)=>{if(!originalTextSetupActive||e.Button!=MouseButtons.Left||originalTextSetupSpans==null)return;for(int n=0;n<originalTextSetupSpans.Length;n++)if(InputFieldBounds((NativeTextLabel)contextLine,originalTextSetupSpans[n]).Contains(e.X,e.Y)){originalTextSetupField=n;UpdateClassic();OpenOriginalTextValue();break;}};Disposed+=(s,e)=>{originalTextValueBox.Dispose();if(originalTextValueFont!=null)originalTextValueFont.Dispose();};}
