 bool SubmitOriginalTextSetup(string text){if(!originalTextSetupActive)return false;if(originalTextOtherFontPending){var font=LayoutNumbers(text);if(font.Length!=1||font[0]<0||font[0]>99||font[0]!=(int)font[0])throw new NotSupportedException("Enter an extended font number from 0 to 99.");originalTextOtherFontPending=false;BeginOriginalTextSetupFont((int)font[0]);return true;}if(text.Trim().Length==0)return true;ApplyOriginalTextSetupValue(text);return true;}
 void ApplyOriginalTextSetupValue(string text){var values=LayoutNumbers(text);if(values.Length!=1)throw new NotSupportedException("Enter one value for the highlighted text field.");float value=values[0];if(originalTextSetupField==0&&(value<1||value>32||value!=(int)value))throw new NotSupportedException("Text staff must be from1 to32.");originalTextSetup[originalTextSetupField]=value;command.Clear();UpdateClassic();}
 void OpenOriginalTextValue(){var row=(NativeTextLabel)contextLine;var field=originalTextSetupSpans[originalTextSetupField];using(var g=row.CreateGraphics()){float cell;var font=row.FitInputFont(g,out cell);if(originalTextValueFont!=null)originalTextValueFont.Dispose();originalTextValueFont=font;originalTextValueBox.Font=font??row.Font;row.Controls.Add(originalTextValueBox);var bounds=NativeInterfaceText.TextSpan(g,row.Text,font??row.Font,field.ValueStart,field.End-field.ValueStart,row.ClientRectangle);originalTextValueBox.Bounds=new Rectangle((int)Math.Floor(bounds.Left),0,Math.Max(30,(int)Math.Ceiling(bounds.Width+NativeInterfaceText.TextWidth(g," ",font??row.Font))),row.ClientSize.Height);}originalTextValueBox.BackColor=inputHighlightColor;originalTextValueBox.ForeColor=inputHighlightColor.GetBrightness()>.5f?Color.Black:Color.White;originalTextValueBox.Text=originalTextSetup[originalTextSetupField].ToString("R",CultureInfo.InvariantCulture);originalTextValueBox.Show();originalTextValueBox.BringToFront();originalTextValueBox.Focus();originalTextValueBox.SelectAll();}
