 bool OriginalTextSetupKey(KeyEventArgs e){if(!originalTextSetupActive)return false;if(originalTextValueBox.Focused){if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;Safe(()=>{ApplyOriginalTextSetupValue(originalTextValueBox.Text);CloseOriginalTextValue();});}else if(e.KeyCode==Keys.Escape){e.SuppressKeyPress=true;CloseOriginalTextValue();}return true;}
  if(originalTextOtherFontPending&&e.KeyCode!=Keys.Escape){if(e.KeyCode>=Keys.F1&&e.KeyCode<=Keys.F12)e.SuppressKeyPress=true;return true;}
  if(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right){e.SuppressKeyPress=true;Safe(()=>{if(command.Text.Length!=0)ApplyOriginalTextSetupValue(command.Text);originalTextSetupField=(originalTextSetupField+(e.KeyCode==Keys.Right?1:5))%6;UpdateClassic();});return true;}
  if(e.KeyCode==Keys.Escape){e.SuppressKeyPress=true;if(originalTextOtherFontPending){originalTextOtherFontPending=false;command.Clear();UpdateClassic();return true;}originalTextOtherFontPending=false;originalTextSetupActive=false;((NativeCommandBox)command).CaptureVerticalNavigation=false;command.Clear();Message("");UpdateClassic();return true;}
