 }
 bool OriginalTextFunction(int key){if(originalTextSetupActive){if(key==7){if(command.Text.Length!=0)ApplyOriginalTextSetupValue(command.Text);originalTextOtherFontPending=true;command.Clear();Message("Enter an extended font number. (0 to 99) ->");return true;}if(key<1||key>6)throw new NotSupportedException("This text-font selection still requires original verification.");if(command.Text.Length!=0)ApplyOriginalTextSetupValue(command.Text);int[] fonts={0,2,1,3,4,5};BeginOriginalTextSetupFont(fonts[key-1]);return true;}if(originalTextDraft!=null){if(originalTextDraft.Units!=null||originalTextDraft.ReadFile||key<1||key>7)throw new NotSupportedException("This function key in the active text-entry phase still requires original verification.");string[] controls={"_00","_02","_01","_03","_04","??","!!"};command.SelectedText=controls[key-1];command.Focus();return true;}return false;}
 void BeginOriginalTextSetupFont(int font){var entry=OriginalTextDraft(new[]{originalTextSetup[0],originalTextSetup[1],originalTextSetup[2],originalTextSetup[3],originalTextSetup[4]},true);entry.Lyrics=entry.Item.P(3)==0;entry.Item.Set(7,originalTextSetup[5]);entry.FromSetup=true;originalTextDraft=entry;originalTextFont=font;originalTextSetupActive=false;command.Text="_"+font.ToString("00");command.SelectionStart=command.Text.Length;Message("Type up to 160 characters (<ESC> to Exit).");UpdateClassic();command.Focus();}
 bool UpdateOriginalTextContext(){if(originalTextDraft==null&&!originalTextSetupActive)return false;var row=(NativeTextLabel)contextLine;row.HighlightLength=0;if(originalTextSetupActive){string[] names={"Staff","Horz","Vert","Spacing","H.Size","V.Size"};var spans=new InputFieldSpan[6];var line=new StringBuilder();for(int n=0;n<6;n++){if(n!=0)line.Append("  ");int start=line.Length;line.Append(names[n]+" = ");int valueStart=line.Length;string value=n<3?originalTextSetup[n].ToString(CultureInfo.InvariantCulture):ExportFixed(originalTextSetup[n],2);line.Append(value);spans[n]=new InputFieldSpan{Start=start,ValueStart=valueStart,End=line.Length,Value=value};if(n==originalTextSetupField){row.HighlightStart=start;row.HighlightLength=line.Length-start;}}originalTextSetupSpans=spans;row.FitInputRow=true;row.Cursor=Cursors.IBeam;row.HighlightColor=inputHighlightColor;row.Text=line.ToString();Message(originalTextOtherFontPending?"Enter an extended font number. (0 to 99) ->":"TEXT INPUT    Adjust Parameters, then select Font to begin.   Press ESC to Exit");InputMenu(new[]{"TIMES","ITALIC","BOLD","BOLD ITAL","HELVT","HELVT BOLD","OTHER",""},8);}else{row.FitInputRow=false;row.Text="";row.Cursor=Cursors.Default;InputMenu(new[]{"TIMES","ITALIC","BOLD","BOLD ITAL","HELVT","ONE DASH","DASHES",""},8);}row.Invalidate();return true;}
